extracted_python_code:
result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(status == 'success')) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

active_customers_by_country = Customers.WHERE(
    (status == 'Active') & (join_date >= '2023-01-01')
).PARTITION(name="country_groups", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

top_2_bought_tickers = Transactions.WHERE(
    (transaction_type == 'buy') &
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(name="ticker_groups", by=(ticker_symbol)).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

customer_metrics = Broker.CALCULATE(
    start_date=DATETIME('now', 'start of month', '-6 months'),
    end_date=DATETIME('now', 'start of month')
).Customers.WHERE(
    (join_date >= start_date) & (join_date < end_date)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), LPAD(MONTH(join_date), 2, '0'))
).PARTITION(name="monthly_groups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

result = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(name="country_group", by=(country)).CALCULATE(
    country=country,
    AR = 100.0 * COUNT(Customers.WHERE(status == 'active')) / COUNT(Customers)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Tickers.WHERE(
    HAS(transactions_of.WHERE(
        (transaction_type == "sell") & 
        (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
    )) == 1
).CALCULATE(
    ticker_symbol=symbol,
    spm=100.0 * (
        SUM(transactions_of.WHERE(
            (transaction_type == "sell") & 
            (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
        ).amount) - 
        SUM(transactions_of.WHERE(
            (transaction_type == "sell") & 
            (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
        ).CALCULATE(total_costs=tax + commission).total_costs)
    ) / SUM(transactions_of.WHERE(
        (transaction_type == "sell") & 
        (DATEDIFF("days", date_time, DATETIME("now")) <= 30)
    ).amount)
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(
    name="ticker_groups", by=(ticker_id)
).CALCULATE(
    ticker_id=ticker_id
)

lowest_price_vti = Broker.CALCULATE(
    lowest_daily_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & (DATEDIFF("days", date, 'now') <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(Transactions.WHERE(DATEDIFF("days", customer.join_date, 'now') <= 70))
)

monthly_average_prices = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    (MONTH(date_time) <= 3)
).CALCULATE(
    month=MONTH(date_time)
).PARTITION(
    name="monthly_transactions",
    by=(month)
).CALCULATE(
    month=month,
    average_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="model_group", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) < 7))
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_weekend_payments_to_utility_co=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Drugs.WHERE(
    HAS(treatments_used_in.WHERE(~(end_dt == None))) == 1
).CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            ~(end_dt == None)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, '@gmail.com') | ENDSWITH(email, '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_in_last_6_months = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) & 
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

avg_patient_weight = Drugs.WHERE(drug_name == 'Drugalin').CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

male_patient_caw = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

npi_by_year = Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_new_patients", by=(first_treatment_year)
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPI=num_new_patients - PREV(num_new_patients, by=year.ASC())
).ORDER_BY(year.ASC())

private_insured_female_patients = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'female') & (ins_type == 'private')))
)

# Find doctors who have prescribed biologic drugs and get their distinct states
result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "Biologic")) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

insurance_type_performance = Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=insurance_type
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(
    5, by=avg_pasi_score.ASC()
)

top_diagnoses_by_itch_score = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diagnosis_name=diag_name,
    num_patients=NDISTINCT(treatments_for.patient.patient_id),
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas)
).TOP_K(
    3,
    by=max_itch_score.DESC()
)

top_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    doc_speciality=doctor.speciality
).PARTITION(
    name="specialties", by=(doc_speciality)
).CALCULATE(
    speciality=doc_speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(
    3, by=total_drug_amount.DESC()
)

avg_patient_age = DermTreatment.CALCULATE(
    avg_age=ROUND(AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    ), 0)
)

user_session_duration_analysis = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

tuc_past_month = Ewallet.CALCULATE(
    TUC=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

successful_and_total_transactions = Ewallet.CALCULATE(
    successful_transactions=COUNT(
        Transactions.WHERE(
            (created_at >= DATETIME('now', 'start of month', '-1 month')) &
            (created_at < DATETIME('now', 'start of month')) &
            (status == 'success')
        )
    ),
    total_transactions=COUNT(
        Transactions.WHERE(
            (created_at >= DATETIME('now', 'start of month', '-1 month')) &
            (created_at < DATETIME('now', 'start of month'))
        )
    )
)

previous_month_str = successful_and_total_transactions.CALCULATE(
    previous_month_str=IFF(
        total_transactions > 0,
        successful_transactions / total_transactions,
        0.0
    )
)

result = Merchants.CALCULATE(
    m_created_at=created_at
).CALCULATE(
    mid=mid,
    name=name,
    coupon_count=COUNT(coupons.WHERE(
        (YEAR(created_at) == YEAR(m_created_at)) &
        (MONTH(created_at) == MONTH(m_created_at))
    ))
).TOP_K(1, by=coupon_count.DESC())

result = Users.WHERE(LOWER(country) == 'us').CALCULATE(
    username=username,
    unread_promo_notifications=COUNT(
        notifications.WHERE(
            (notification_type == 'promotional') & (status == 'unread')
        )
    )
).WHERE(unread_promo_notifications > 0)

merchant_ids_received_money = Transactions.WHERE(receiver_type == 1).PARTITION(name="merch_tx", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'TRANSACTION').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

top_merchants_by_amount = Merchants.CALCULATE(
    merchant_name=name,
    total_transaction_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
    ).amount),
    total_number_of_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
    ))
).WHERE(
    total_number_of_transactions > 0
).TOP_K(
    2, by=total_transaction_amount.DESC()
)

result = Ewallet.CALCULATE(
    min_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_tx_limit_daily=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_daily),
    avg_tx_limit_monthly=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_monthly)
)

# Find merchants whose earliest coupon was created within a year of registration
result = Merchants.WHERE(HAS(coupons) == 1).CALCULATE(
    merchant_id=mid,
    registration_date=created_at,
    earliest_coupon_id=coupons.WHERE(
        RANKING(by=start_date.ASC(), per="Merchants") == 1
    ).SINGULAR().cid,
    earliest_coupon_start_date=coupons.WHERE(
        RANKING(by=start_date.ASC(), per="Merchants") == 1
    ).SINGULAR().start_date
).WHERE(
    DATEDIFF("days", registration_date, earliest_coupon_start_date) <= 365
)
